-- =========================================================================
-- SAMAM / KL SAC — LCH domain badge seed
-- Generated from src/app/Data/activities-mock.ts (210 LCH activities)
-- Safe to re-run: badge_definitions rows are upserted by `code`,
-- and the activity_catalogue link is a single idempotent UPDATE...JOIN.
-- =========================================================================

-- 1. Make sure every column this script needs actually exists.
--    (No-ops if already present — MySQL 8.0.29+ required for IF NOT EXISTS.)
ALTER TABLE badge_definitions
    ADD COLUMN IF NOT EXISTS type ENUM('activity','milestone') DEFAULT 'activity',
    ADD COLUMN IF NOT EXISTS target_value INT DEFAULT 1,
    ADD COLUMN IF NOT EXISTS metric VARCHAR(50) DEFAULT 'completion',
    ADD COLUMN IF NOT EXISTS rarity VARCHAR(50) DEFAULT 'Common',
    ADD COLUMN IF NOT EXISTS requirement TEXT,
    ADD COLUMN IF NOT EXISTS color VARCHAR(20) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS bg_color VARCHAR(20) DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS competencies JSON DEFAULT NULL,
    ADD COLUMN IF NOT EXISTS is_active TINYINT(1) DEFAULT 1;

-- 2. Upsert one badge per LCH activity (210 rows).
--    code = B-<activity code>, so it lines up with the existing
--    `Complete <code>` requirement convention the verify page already parses.

INSERT INTO badge_definitions (code, name, description, icon, domain, type, rarity, target_value, metric, requirement, color, bg_color, competencies, is_active) VALUES ('B-DC-A01', 'Dance Enthusiast', 'Awarded for completing "Dance Club Orientation & Open Dance Jam" — This introductory event welcomes new members to the Dance Club by presenting the club''s vision, annual activities, training opportunities, and performance pathways. The session concludes with an open dance jam that encourages interaction, creativity, and community building among participants.', '💃', 'LCH', 'activity', 'Common', 1, 'activity_completion', 'Complete DC-A01', '#7C3AED', '#F5F3FF', '["Communication", "Self-confidence", "Team participation", "Social interaction"]', 1)
ON DUPLICATE KEY UPDATE name = VALUES(name), description = VALUES(description), icon = VALUES(icon), domain = VALUES(domain), type = VALUES(type), rarity = VALUES(rarity), requirement = VALUES(requirement), color = VALUES(color), bg_color = VALUES(bg_color), competencies = VALUES(competencies), is_active = VALUES(is_active);
