-- 3. Link every LCH activity in activity_catalogue to its new badge in one shot.
--    (No-op for any code not present in activity_catalogue yet.)
UPDATE activity_catalogue ac
JOIN badge_definitions bd ON bd.code = CONCAT('B-', ac.code)
SET ac.badge_id = bd.id
WHERE ac.domain = 'LCH';

